// Photos stay in browser memory. Only user-confirmed text is stored locally.
(()=>{
const entry=document.createElement('button');entry.className='photo-entry';entry.innerHTML='<span class="photo-camera">▣</span><span>이름으로 찾기 어렵다면 <strong>포장지 사진으로 읽기</strong></span><span>↗</span>';$('.search-box').after(entry);
const dialog=document.createElement('dialog');dialog.id='photo-dialog';dialog.className='photo-dialog';dialog.setAttribute('aria-labelledby','photo-title');dialog.innerHTML=`<div class="modal-top"><span class="eyebrow">READ YOUR LABEL</span><button class="icon-button" id="close-photo" aria-label="사진 인식 닫기">×</button></div><h2 id="photo-title">포장지를 읽어볼까요?</h2><p class="photo-intro">원재료 표시가 크고 선명하게 보이도록 찍어 주세요.<br>사진은 전송하지 않고 이 브라우저 안에서 읽어요.</p><div class="photo-upload" id="dropzone"><div class="upload-symbol">▣</div><h3>사진 한 장에서 시작해요</h3><p>JPG · PNG · WebP / 최대 20MB<br>사진을 여기에 끌어 놓아도 좋아요.</p><div class="upload-buttons"><button class="primary-button" id="choose-photo">사진 선택</button><button class="secondary-button" id="camera-photo">카메라로 촬영</button></div></div><input type="file" id="photo-file" accept="image/jpeg,image/png,image/webp" hidden><input type="file" id="photo-camera" accept="image/*" capture="environment" hidden><div id="photo-editor" hidden><div class="photo-preview-wrap"><img id="photo-preview" alt="선택한 포장지 사진"><div id="crop-overlay" aria-hidden="true"></div></div><div class="photo-tools"><button class="secondary-button" id="rotate-photo">↻ 90° 회전</button><button class="secondary-button" id="replace-photo">다른 사진</button></div><details class="crop-controls"><summary>원재료 부분만 읽도록 영역 조정</summary><div class="crop-grid">${[['top','위쪽'],['bottom','아래쪽'],['left','왼쪽'],['right','오른쪽']].map(([key,label])=>`<label>${label} 제외 <output id="crop-${key}-value">0%</output><input id="crop-${key}" data-crop="${key}" type="range" min="0" max="85" value="0" aria-label="${label} 제외 비율"></label>`).join('')}</div></details><button class="primary-button full-width" id="recognize-photo">사진 속 글자 읽기</button><p class="photo-privacy">첫 실행에는 한국어·영어 인식 자료를 불러와 잠시 걸릴 수 있어요. 사진과 인식한 글자는 외부로 보내지 않아요.</p></div><div id="ocr-progress" class="ocr-progress" hidden><div><span id="ocr-status" role="status">인식 준비 중이에요…</span><button id="cancel-ocr">중단</button></div><progress id="ocr-bar" max="100" value="0" aria-label="사진 인식 진행률"></progress></div><p id="photo-error" class="photo-error" role="alert" hidden></p><section id="ocr-result" hidden><span class="badge photo-badge">사진에서 읽은 정보 · 확인 전</span><h3>포장지와 나란히 확인해 주세요</h3><p class="photo-help">작은 글씨·곡면·빛 반사로 글자가 틀릴 수 있어요. 제품명과 원재료를 직접 확인하고 수정할 수 있어요.</p><label class="photo-field">제품 이름 <input id="photo-product-name" maxlength="150" placeholder="포장지에 적힌 이름을 입력해 주세요"></label><label class="photo-field">인식한 원문 <textarea id="photo-raw" rows="7" maxlength="20000" placeholder="사진에서 읽은 전체 글자가 여기에 표시돼요"></textarea></label><label class="photo-field">확인한 원재료 표시 <textarea id="photo-ingredients" rows="4" maxlength="10000" placeholder="원문에서 원재료 표시 부분을 옮기거나 수정해 주세요"></textarea></label><label class="confirm-label"><input type="checkbox" id="confirm-photo">포장지와 비교해 제품명과 원재료를 확인했어요.</label><div class="photo-result-actions"><button class="secondary-button" id="search-photo">이 이름으로 식품 검색</button><button class="primary-button" id="save-photo" disabled>확인한 노트 저장</button></div><p class="photo-privacy">확인한 텍스트만 이 브라우저에 저장해요. 사진은 저장하지 않아요. 공공데이터와 자동으로 같은 제품으로 연결하지 않아요.</p></section><section class="photo-notes-section"><h3>내가 확인한 포장지 노트 <span id="photo-note-count">0</span></h3><div id="photo-notes"></div></section>`;
document.body.append(dialog);
let notes=[];try{const n=JSON.parse(localStorage.getItem('hanip-photo-notes-v1')||'[]');if(Array.isArray(n))notes=n.filter(x=>x&&typeof x.id==='string'&&typeof x.name==='string'&&typeof x.ingredients==='string'&&typeof x.date==='string').slice(0,50)}catch{}
let image=null,url=null,rotation=0,busy=false,run=0,worker=null,library=null;const crop={top:0,bottom:0,left:0,right:0};
const q=s=>dialog.querySelector(s),err=message=>{q('#photo-error').textContent=message;q('#photo-error').hidden=!message};
function notesRender(){q('#photo-note-count').textContent=notes.length;q('#photo-notes').innerHTML=notes.length?notes.map(n=>`<article class="photo-note"><div><span class="badge photo-badge">사진 기록</span><strong>${escapeHTML(n.name)}</strong><small>${escapeHTML(n.date)} · 포장지 직접 확인</small></div><p>${escapeHTML(n.ingredients).replace(/\n/g,'<br>')}</p><button class="text-button" data-remove-note="${escapeHTML(n.id)}">기록 삭제</button></article>`).join(''):'<p class="photo-help">사진을 읽고 확인한 내용을 여기 모아둘 수 있어요.</p>';q('#photo-notes').querySelectorAll('.photo-badge').forEach(b=>b.textContent='사진 기록')}
entry.onclick=()=>{notesRender();dialog.showModal();dialog.scrollTop=0};q('#close-photo').onclick=()=>dialog.close();dialog.addEventListener('click',e=>{if(e.target===dialog){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)dialog.close()}});
function clearImage(){if(url)URL.revokeObjectURL(url);url=null;image=null;q('#photo-preview').removeAttribute('src');q('#photo-editor').hidden=true;q('#dropzone').hidden=false}
async function cancel(){run++;busy=false;if(worker){const old=worker;worker=null;await old.terminate().catch(()=>{})}q('#ocr-progress').hidden=true;q('#recognize-photo').disabled=false;q('#rotate-photo').disabled=false;q('#replace-photo').disabled=false;q('.crop-controls').inert=false}
dialog.addEventListener('close',()=>{cancel();clearImage();q('#ocr-result').hidden=true;q('#photo-raw').value='';q('#photo-ingredients').value='';q('#photo-product-name').value='';err('');entry.focus()});q('#cancel-ocr').onclick=()=>{cancel();err('인식을 중단했어요. 영역을 조정하거나 다시 시도해 주세요.')};
q('#choose-photo').onclick=()=>q('#photo-file').click();q('#camera-photo').onclick=()=>q('#photo-camera').click();q('#replace-photo').onclick=()=>q('#photo-file').click();
function resetCrop(){Object.keys(crop).forEach(key=>{crop[key]=0;q('#crop-'+key).value=0;q('#crop-'+key+'-value').textContent='0%'});updateCrop()}
function updateCrop(){q('#crop-overlay').style.cssText=`inset:${crop.top}% ${crop.right}% ${crop.bottom}% ${crop.left}%;`;}
async function loadFile(file){if(!file)return;if(busy){err('인식을 중단한 다음 다른 사진을 선택해 주세요.');return}if(!['image/jpeg','image/png','image/webp'].includes(file.type)){err('JPG, PNG, WebP 사진을 선택해 주세요. HEIC 사진은 JPG로 변환해 주세요.');return}if(file.size>20*1024*1024){err('20MB 이하의 사진을 선택해 주세요.');return}err('');const candidateUrl=URL.createObjectURL(file),candidateImage=new Image();try{await new Promise((resolve,reject)=>{candidateImage.onload=resolve;candidateImage.onerror=reject;candidateImage.src=candidateUrl});if(candidateImage.width*candidateImage.height>40000000)throw new Error('large');if(!dialog.open){URL.revokeObjectURL(candidateUrl);return}if(url)URL.revokeObjectURL(url);url=candidateUrl;image=candidateImage;rotation=0;resetCrop();q('#photo-preview').src=url;q('#photo-editor').hidden=false;q('#dropzone').hidden=true;q('#ocr-result').hidden=true;q('#confirm-photo').checked=false;q('#save-photo').disabled=true;q('#photo-raw').value='';q('#photo-ingredients').value='';q('#photo-product-name').value=''}catch(e){URL.revokeObjectURL(candidateUrl);err(e?.message==='large'?'사진이 너무 커요. 원재료 부분을 잘라 다시 선택해 주세요.':'사진을 열지 못했어요. 다른 사진을 선택해 주세요.')}}
['photo-file','photo-camera'].forEach(id=>q('#'+id).onchange=e=>{loadFile(e.target.files[0]);e.target.value=''});const drop=q('#dropzone');drop.ondragover=e=>{e.preventDefault();drop.classList.add('dragover')};drop.ondragleave=()=>drop.classList.remove('dragover');drop.ondrop=e=>{e.preventDefault();drop.classList.remove('dragover');loadFile(e.dataTransfer.files[0])};
q('#rotate-photo').onclick=()=>{if(!image||busy)return;rotation=(rotation+90)%360;const c=document.createElement('canvas');c.width=rotation%180?image.height:image.width;c.height=rotation%180?image.width:image.height;const ctx=c.getContext('2d');ctx.translate(c.width/2,c.height/2);ctx.rotate(rotation*Math.PI/180);ctx.drawImage(image,-image.width/2,-image.height/2);q('#photo-preview').src=c.toDataURL('image/jpeg',.92);resetCrop()};
q('.crop-grid').oninput=e=>{const key=e.target.dataset.crop;if(!key)return;const opposite={top:'bottom',bottom:'top',left:'right',right:'left'}[key];crop[key]=Math.min(Number(e.target.value),90-crop[opposite]);e.target.value=crop[key];q('#crop-'+key+'-value').textContent=crop[key]+'%';updateCrop()};
function loadLibrary(){if(window.Tesseract)return Promise.resolve();if(library)return library;library=new Promise((resolve,reject)=>{const s=document.createElement('script');s.src='vendor/tesseract.min.js';s.onload=resolve;s.onerror=()=>{s.remove();library=null;reject(new Error('load'))};document.head.append(s)});return library}
async function recognize(){if(!image||busy)return;err('');q('#ocr-result').hidden=true;busy=true;const thisRun=++run;q('#recognize-photo').disabled=true;q('#rotate-photo').disabled=true;q('#replace-photo').disabled=true;q('.crop-controls').inert=true;q('#ocr-progress').hidden=false;q('#ocr-bar').value=0;q('#ocr-status').textContent='글자 인식 자료를 준비하고 있어요…';let timer;try{
 await loadLibrary();if(thisRun!==run)return;
 const timeout=new Promise((_,reject)=>{timer=setTimeout(()=>reject(new Error('timeout')),120000)});
 const job=(async()=>{const base=new URL('vendor/',location.href).href;const created=await Tesseract.createWorker('kor+eng',1,{workerPath:base+'worker.min.js',corePath:base,langPath:base.replace(/\/$/,''),workerBlobURL:false,logger:m=>{if(thisRun!==run)return;const recognizing=m.status==='recognizing text';q('#ocr-status').textContent=recognizing?'포장지 속 글자를 읽고 있어요…':'한국어·영어 인식을 준비하고 있어요…';q('#ocr-bar').value=recognizing?35+Math.round(m.progress*65):Math.round((m.progress||0)*30)}});if(thisRun!==run){await created.terminate();throw new Error('cancelled')}worker=created;await worker.setParameters({tessedit_pageseg_mode:'6',preserve_interword_spaces:'1',user_defined_dpi:'300'});const preview=q('#photo-preview');await preview.decode();const iw=preview.naturalWidth,ih=preview.naturalHeight,sx=iw*crop.left/100,sy=ih*crop.top/100,sw=iw*(100-crop.left-crop.right)/100,sh=ih*(100-crop.top-crop.bottom)/100;const scale=Math.min(2,2400/Math.max(sw,sh));const canvas=document.createElement('canvas');canvas.width=Math.round(sw*scale);canvas.height=Math.round(sh*scale);const ctx=canvas.getContext('2d');ctx.fillStyle='white';ctx.fillRect(0,0,canvas.width,canvas.height);ctx.drawImage(preview,sx,sy,sw,sh,0,0,canvas.width,canvas.height);return worker.recognize(canvas.toDataURL('image/png'),{}, {text:true})})();
 const result=await Promise.race([job,timeout]);if(thisRun!==run)return;const text=result.data.text.trim();if(!text){err('읽을 수 있는 글자를 찾지 못했어요. 원재료 부분을 더 가까이 찍거나 인식 영역을 조정해 주세요.');return}q('#photo-raw').value=text;q('#ocr-result').hidden=false;q('#confirm-photo').checked=false;q('#save-photo').disabled=true;const found=text.match(/(?:원재료명(?:\s*및\s*함량)?|원재료\s*및\s*함량|원재료)\s*[:：]?\s*([\s\S]+)/);if(found)q('#photo-ingredients').value=found[1].split(/(?:영양정보|영양성분|보관방법|소비기한|유통기한|품목보고번호|품목제조보고번호)/)[0].trim().slice(0,10000);q('#ocr-status').textContent='글자를 읽었어요. 포장지와 비교해 주세요.';toast('사진을 읽었어요. 틀린 글자는 수정해 주세요.');q('#ocr-result').scrollIntoView({behavior:'smooth',block:'start'});
 }catch(e){if(thisRun===run)err(e?.message==='timeout'?'인식 시간이 길어 중단했어요. 사진 영역을 줄이고 다시 시도해 주세요.':'글자 인식을 완료하지 못했어요. 사진을 바꾸거나 잠시 후 다시 시도해 주세요.')}finally{clearTimeout(timer);if(thisRun===run){await cancel()}}}
q('#recognize-photo').onclick=recognize;
function validateSave(){q('#save-photo').disabled=!q('#confirm-photo').checked||!q('#photo-product-name').value.trim()||!q('#photo-ingredients').value.trim()}
q('#confirm-photo').addEventListener('input',validateSave);['photo-product-name','photo-ingredients'].forEach(id=>q('#'+id).addEventListener('input',()=>{q('#confirm-photo').checked=false;validateSave()}));
q('#save-photo').onclick=()=>{validateSave();if(q('#save-photo').disabled)return;if(notes.length>=50){err('최대 50개까지 보관할 수 있어요. 이전 기록을 정리해 주세요.');return}const item={id:crypto.randomUUID(),name:q('#photo-product-name').value.trim(),ingredients:q('#photo-ingredients').value.trim(),date:new Date().toLocaleDateString('ko-KR'),source:'포장지 사진 · 사용자 확인'};try{localStorage.setItem('hanip-photo-notes-v1',JSON.stringify([item,...notes]));notes.unshift(item);notesRender();q('#confirm-photo').checked=false;validateSave();toast('확인한 포장지 노트를 저장했어요.')}catch{err('브라우저에 저장하지 못했어요. 저장 공간이나 브라우저 설정을 확인해 주세요.')}};
q('#search-photo').onclick=()=>{const name=q('#photo-product-name').value.trim();if(!name){err('검색할 제품 이름을 입력해 주세요.');q('#photo-product-name').focus();return}state.view='all';state.category='전체';state.age='all';state.query=name;$('#search').value=name;syncFilters();render();dialog.close();$('#search').focus();$('#search').scrollIntoView({behavior:'smooth',block:'center'})};
q('#photo-notes').onclick=e=>{const button=e.target.closest('[data-remove-note]');if(!button)return;const next=notes.filter(n=>n.id!==button.dataset.removeNote);try{localStorage.setItem('hanip-photo-notes-v1',JSON.stringify(next));notes=next;notesRender();toast('포장지 기록을 삭제했어요.')}catch{err('기록을 삭제하지 못했어요. 다시 시도해 주세요.')}};
notesRender();
const guideParagraph=$('#guide-dialog .guide-source p:last-child');guideParagraph.textContent='현재 버전은 총 60개 식품의 검색과 포장지 사진 인식을 제공해요. 기존 10개는 즐겨찾기에 기본 추가돼요. 사진은 브라우저 안에서 읽고, 확인한 텍스트만 별도 노트로 저장해요. 실시간 공공데이터 조회는 아직 연결되지 않았어요. 저장 정보는 이 브라우저에 보관돼요.';
})();
